contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    event Forwarded(address from, address to, uint256 value);

    function run(address from, address[] memory tos, uint256 v) public payable {
        require(tos.length > 0);

        address[] memory recipients = new address[](tos.length);
        Forwarder[] memory forwarders = new Forwarder[](tos.length);
        for (uint256 i = 0; i < tos.length; i++) {
            forwarders[i] = new Forwarder();
            recipients[i] = address(forwarders[i]);
        }

        bool ok = c.transfer(from, address(this), recipients, v);

        assert(ok);

        for (uint256 i = 0; i < forwarders.length; i++) {
            assert(forwarders[i].sawFrom() == from);
            assert(forwarders[i].sawValue() == v);
            assert(forwarders[i].sawTo() == recipients[i]);
        }
    }

    function transferFrom(address from, address to, uint256 value) external returns (bool) {
        return true;
    }

    receive() external payable {}
}

contract Forwarder {
    address public sawFrom;
    address public sawTo;
    uint256 public sawValue;
    uint256 public calls;

    function transferFrom(address from, address to, uint256 value) external returns (bool) {
        sawFrom = from;
        sawTo = to;
        sawValue = value;
        calls++;
        return true;
    }
}

